#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAXN 305
#define MAXR 2705

int P[MAXN];
int A[MAXN];
int dp[MAXN][MAXR];
int maxR[MAXN];

int main() {
    int N, K, T;
    scanf("%d %d %d", &N, &K, &T);

    for (int i = 1; i <= N; ++i) {
        scanf("%d", &P[i]);
    }

    int cnt = 0;
    for (int i = 1; i <= N; ++i) {
        int g;
        scanf("%d", &g);
        if (g == 1) {
            A[++cnt] = i;
        }
    }

    int sumP = 0;
    for (int i = 1; i <= N; ++i) sumP += P[i];

    int maxReward = sumP;
    int INF = T + 1;

    for (int i = 0; i <= K; ++i) {
        for (int r = 0; r <= maxReward; ++r) {
            dp[i][r] = INF;
        }
        maxR[i] = -1;
    }

    dp[0][0] = 0;
    maxR[0] = 0;

    for (int j = 1; j <= N; ++j) {
        int pj = P[j];
        int max_i = (K < j) ? K : j;

        for (int i = max_i; i >= 1; --i) {
            int prev_max = maxR[i - 1];
            if (prev_max < 0) continue;

            int cost = abs(A[i] - j);

            for (int r = 0; r <= prev_max; ++r) {
                int prev = dp[i - 1][r];
                if (prev != INF) {
                    int newCost = prev + cost;
                    if (newCost < dp[i][r + pj]) {
                        dp[i][r + pj] = newCost;
                        if (r + pj > maxR[i]) {
                            maxR[i] = r + pj;
                        }
                    }
                }
            }
        }
    }

    printf("%d\n", maxR[K]);
    return 0;
}
